public static class Baseline { public static long Run(int[] values, int threshold) { List<int> selected = new List<int>(values.Length); for (int i = 0; i < values.Length; i++) { if (values[i] < threshold) { selected.Add(values[i]); } } int[] selectedArray = selected.ToArray(); long sum = 0; for (int i = 0; i < selectedArray.Length; i++) { sum += Math.Abs((long)selectedArray[i]); } return sum; } }